modelSource:
cube('analytics_period_inputs', {
  sql: 'SELECT * FROM cssql_oracle.analytics_period_inputs',
  access_policy: [{ group: 'semantic_analyst', member_level: { includes: '*' },
    row_level: { filters: [{ member: 'tenant', operator: 'equals', values: ['A'] }] } }],
  dimensions: {
    id: { sql: 'id', type: 'number', primary_key: true, public: true },
    tenant: { sql: 'tenant', type: 'string' },
    observed_at: { sql: 'observed_at', type: 'time' }
  },
  measures: { amount: { sql: 'amount', type: 'sum' } }
});

setupSQL:
CREATE SCHEMA cssql_oracle;

  CREATE TABLE cssql_oracle.analytics_period_inputs (
    id integer PRIMARY KEY, tenant text NOT NULL, observed_at timestamp NOT NULL, amount numeric NOT NULL
  );
  INSERT INTO cssql_oracle.analytics_period_inputs VALUES
    (1,'A','2024-01-15',100), (2,'A','2024-02-15',200), (3,'A','2024-03-15',300),
    (4,'B','2024-01-15',10000), (5,'B','2024-02-15',20000), (6,'B','2024-03-15',30000);

cases.oracle:
-- oracle:mc04_row_march_truth
WITH monthly AS (
  SELECT date_trunc('month', observed_at) AS month, sum(amount) AS current
  FROM cssql_oracle.analytics_period_inputs WHERE tenant = 'A' AND id = 3 GROUP BY 1
), observed AS (SELECT month, current, lag(current) OVER (ORDER BY month) AS prior FROM monthly)
SELECT month, current, prior, (current - prior) / NULLIF(prior, 0) AS growth FROM observed ORDER BY month;

-- oracle:mc04_row_gap_truth
WITH monthly AS (
  SELECT date_trunc('month', observed_at) AS month, sum(amount) AS current
  FROM cssql_oracle.analytics_period_inputs WHERE tenant = 'A' AND id IN (1, 3) GROUP BY 1
), observed AS (SELECT month, current, lag(current) OVER (ORDER BY month) AS prior FROM monthly)
SELECT month, current, prior, (current - prior) / NULLIF(prior, 0) AS growth FROM observed ORDER BY month;

